def count_key(s):
    # 26 字母计数签名：互为异位词的字符串该签名必然相同
    cnt = [0] * 26
    for ch in s:
        cnt[ord(ch) - ord('a')] += 1
    return tuple(cnt)


def groupAnagrams_brute(strs):
    # groups[i] = (代表词的签名, 组内单词列表)
    groups = []
    for s in strs:
        key = count_key(s)
        for g in groups:
            if g[0] == key:        # 只需与每组代表词比较
                g[1].append(s)
                break
        else:                      # 没有任何组能收下它，自开新组
            groups.append((key, [s]))
    return [g[1] for g in groups]

def groupAnagrams_sort(strs):
    groups = {}                     # 签名 -> 组内单词
    for s in strs:
        # 排序结果是唯一的规范形态：互为异位词的词排序后逐位相同
        key = tuple(sorted(s))
        groups.setdefault(key, []).append(s)
    return list(groups.values())

