class Solution:
    def groupAnagrams(self, strs: List[str]) -> List[List[str]]:
        # groups: 计数签名 -> 该签名下的所有单词（defaultdict 让新 key 自动获得空列表）
        groups = defaultdict(list)
        for s in strs:
            # cnt[i] 表示字母 chr(i + ord('a')) 在 s 中出现的次数
            cnt = [0] * 26
            for ch in s:
                cnt[ord(ch) - ord('a')] += 1
            # list 不可哈希，必须转成 tuple 才能充当字典的 key
            groups[tuple(cnt)].append(s)
        # 字典的每个 value 就是一个异位词组
        return list(groups.values())

