class Solution {
public:
    vector<vector<string>> groupAnagrams(vector<string>& strs) {
        // 计数签名：互为异位词的字符串 26 字母计数完全相同，计数即分组 key
        unordered_map<string, vector<string>> groups;
        for (const string& s : strs) {
            int cnt[26] = {0};
            for (char c : s) ++cnt[c - 'a'];     // 统计每个字母出现次数
            string key;
            for (int i = 0; i < 26; ++i) {
                key += to_string(cnt[i]);        // 计数转十进制
                key += '#';                      // 分隔符防『1,12』与『12,1』拼接歧义
            }
            groups[key].push_back(s);            // 同签名归同组
        }
        vector<vector<string>> ans;
        ans.reserve(groups.size());
        for (auto& [key, list] : groups) ans.push_back(move(list));
        return ans;
    }
};

