// ACM 模式：完整可运行程序（stdin -> stdout）
// 输入格式：
//   第一行：n（单词个数）
//   接下来 n 行：每行一个单词（仅小写字母，行内无空格）
// 输出格式：
//   每组一行，组内单词按输入顺序用空格分隔；组的先后按各组首词出现的顺序
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);   // 关闭同步，读入更快
    cin.tie(nullptr);

    int n;
    cin >> n;
    cin.ignore();                            // 跳过 n 之后行内残留的换行
    vector<string> words(n);
    for (int i = 0; i < n; ++i) {
        getline(cin, words[i]);              // 逐行读单词，天然支持空串
        while (!words[i].empty() && (words[i].back() == '\r' || words[i].back() == ' '))
            words[i].pop_back();             // 去掉行尾残留
    }

    unordered_map<string, int> idx;          // 签名 -> 组编号
    vector<vector<string>> groups;           // 用向量保持『首词出现顺序』
    for (const string& w : words) {
        int cnt[26] = {0};
        for (char c : w) ++cnt[c - 'a'];     // 26 字母计数签名
        string key;
        for (int i = 0; i < 26; ++i) {
            key += to_string(cnt[i]);
            key += '#';                      // 分隔符防拼接歧义
        }
        auto it = idx.find(key);
        if (it == idx.end()) {               // 新签名：开新组并登记顺序
            idx[key] = (int)groups.size();
            groups.push_back({w});
        } else {
            groups[it->second].push_back(w); // 旧签名：并入已有组
        }
    }

    string out;
    for (const auto& g : groups) {
        for (size_t i = 0; i < g.size(); ++i) {
            if (i) out += ' ';               // 组内单词空格分隔
            out += g[i];
        }
        out += '\n';                         // 每组一行
    }
    cout << out;
    return 0;
}

