def longestConsecutive_sort(nums):
    if not nums:
        return 0
    nums = sorted(nums)          # 用 sorted 拷贝，不修改调用方的数组
    best, cur = 1, 1             # cur: 以当前元素结尾的连续段长
    for i in range(1, len(nums)):
        if nums[i] == nums[i - 1]:
            continue             # 跳过重复值，不能计入段长
        if nums[i] == nums[i - 1] + 1:
            cur += 1             # 与前一个衔接，段延长
        else:
            cur = 1              # 断档，当前元素成为新段的起点
        best = max(best, cur)
    return best

