class Solution {
public:
    int longestConsecutive(vector<int>& nums) {
        unordered_set<int> seen(nums.begin(), nums.end());  // 去重 + O(1) 存在性查询
        int best = 0;
        for (int x : seen) {
            if (seen.count(x - 1)) continue;   // 不是段头，所属段会由段头统计，防重复计数
            int length = 1;                    // x 自己算段长 1
            while (seen.count(x + length)) ++length;   // 从段头向右扩展到断档
            best = max(best, length);
        }
        return best;
    }
};

