class Solution:
    def firstMissingPositive(self, nums: List[int]) -> int:
        n = len(nums)
        # 原地哈希：数组本身充当哈希表（相当于一张 {} 映射：值 v -> 下标 v-1），不花额外空间
        for i in range(n):
            # 只要 nums[i] 是 [1, n] 内的值且还没归位，就把它换到下标 nums[i]-1 处
            while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
                j = nums[i] - 1            # 值 nums[i] 应该待的位置
                nums[i], nums[j] = nums[j], nums[i]
        # 归位完成后，第一个不满足 nums[i] == i+1 的位置就是缺失的最小正数
        for i in range(n):
            if nums[i] != i + 1:
                return i + 1
        # 1..n 全部出现在数组中，答案是 n+1
        return n + 1

