class Solution {
public:
    int firstMissingPositive(vector<int>& nums) {
        int n = (int)nums.size();
        // 原地哈希：数组本身当哈希表，值 v 的家在下标 v-1，零额外空间
        for (int i = 0; i < n; ++i) {
            // 值在 [1,n] 内且目标位置未归位才交换；目标位置已是该值时停，防重复值死循环
            while (nums[i] >= 1 && nums[i] <= n && nums[nums[i] - 1] != nums[i]) {
                swap(nums[i], nums[nums[i] - 1]);   // 把 nums[i] 换回自己的家
            }
        }
        // 归位完成后，第一个 nums[i] != i+1 的位置暴露缺失的最小正数
        for (int i = 0; i < n; ++i) {
            if (nums[i] != i + 1) return i + 1;
        }
        return n + 1;   // 1..n 全部在位
    }
};

