def normalize(s):
    idx, seq = {}, []            # idx: 字符 -> 首次出现的下标
    for i, ch in enumerate(s):
        if ch not in idx:
            idx[ch] = i          # 只在首次出现时登记下标
        seq.append(idx[ch])      # 重复字符复用首次下标
    return seq


def isIsomorphic_pattern(s, t):
