class Solution:
    def isIsomorphic(self, s: str, t: str) -> bool:
        # 两张表缺一不可：s2t 保证 s 侧映射唯一，t2s 保证 t 侧字符不被两个 s 字符占用
        s2t, t2s = {}, {}
        for ch1, ch2 in zip(s, t):
            # s 的字符已登记过：必须仍指向同一个 t 字符，否则冲突
            if ch1 in s2t and s2t[ch1] != ch2:
                return False
            # t 的字符已被其他 s 字符登记：出现多对一，违反双射
            if ch2 in t2s and t2s[ch2] != ch1:
                return False
            s2t[ch1] = ch2           # 登记正向映射
            t2s[ch2] = ch1           # 登记反向映射
        return True

