        // 两张表缺一不可：s2t 防一对多，t2s 防多对一（badc/baba 类反例）
        vector<int> s2t(128, -1), t2s(128, -1);
        for (int i = 0; i < (int)s.size(); ++i) {
            int a = s[i], b = t[i];
            if (s2t[a] != -1 && s2t[a] != b) return false;  // 正向冲突：一对多
            if (t2s[b] != -1 && t2s[b] != a) return false;  // 反向冲突：多对一
            s2t[a] = b;   // 登记正向映射
            t2s[b] = a;   // 登记反向映射
        }
        return true;
    }
};

