    if (ans) {
        vector<int> s2t(128, -1), t2s(128, -1);   // 双向映射表，缺一不可
        for (int i = 0; i < (int)s.size(); ++i) {
            int a = s[i], b = t[i];
            if (s2t[a] != -1 && s2t[a] != b) { ans = false; break; }  // 一对多
            if (t2s[b] != -1 && t2s[b] != a) { ans = false; break; }  // 多对一
            s2t[a] = b;
            t2s[b] = a;
        }
    }
    cout << (ans ? "true" : "false") << endl;
    return 0;
}

