class Solution {
public:
    bool wordPattern(string pattern, string s) {
        // 手动按空格切分出所有单词（不依赖 sstream）
        vector<string> words;
        for (int i = 0; i < (int)s.size(); ++i) {
            if (s[i] == ' ') continue;                   // 跳过空格
            int j = i;
            while (j < (int)s.size() && s[j] != ' ') ++j;
            words.push_back(s.substr(i, j - i));         // 截取一个单词
            i = j;
        }
        // 个数不匹配直接 false（防配对时静默截断）
        if (words.size() != pattern.size()) return false;
        // 双射检查：c2w 防一个字母映射多个单词，w2c 防多字母映射同一单词
        unordered_map<char, string> c2w;
        unordered_map<string, char> w2c;
        for (int i = 0; i < (int)pattern.size(); ++i) {
            char ch = pattern[i];
            const string& word = words[i];
            auto it1 = c2w.find(ch);
            if (it1 != c2w.end() && it1->second != word) return false;  // 正向冲突
            auto it2 = w2c.find(word);
            if (it2 != w2c.end() && it2->second != ch) return false;    // 反向冲突
            c2w[ch] = word;
            w2c[word] = ch;
        }
        return true;
    }
